js("""
(() => {
  const links = Array.from(document.querySelectorAll('a'));
  const embedLinks = links.filter(a => {
    const text = a.textContent.toLowerCase();
    return text.includes('embeddable') && text.includes('64-bit');
  });
  return embedLinks.map(a => ({text: a.textContent.trim(), href: a.href}));
})()
""")

