# First, let's try using js to create a download via fetch
result = js("""(() => {
  // Try to get the file size from headers first
  return fetch('https://www.python.org/ftp/python/3.13.0/python-3.13.0-embed-amd64.zip', {method: 'HEAD'})
    .then(response => {
      const size = response.headers.get('content-length');
      const filename = response.headers.get('content-disposition') || 'python-3.13.0-embed-amd64.zip';
      return {size: size, filename: filename};
    })
    .catch(err => ({error: err.message}));
})()""")
print(result)

